  origin text,
  custom jsonb not null default '{}'::jsonb,
  no integer,
  number text generated always as (case when no is null then null when length(no::text) >= 5 then 'RSK' || no::text else 'RSK' || lpad(no::text, 5, '0') end) stored,
  title text,
  category text,
  cause text,
  event text,
  consequence text,
  owner_id uuid,
  reporter_id uuid,
  reporter_role text,
  assignment_group_id uuid,
  services jsonb,
